"""Render the annotated bibliography and BibTeX from the reference catalog."""

import argparse
import json
import sys
from pathlib import Path

DIRECTORY = Path(__file__).resolve().parents[1] / "docs/references"


def render(catalog: dict) -> dict[str, str]:
    records = catalog["records"]
    date = catalog["access_date"]
    markdown = [
        "# 参考资料库",
        "",
        "<!-- Generated by scripts/render_references.py; edit catalog.json. -->",
        "",
        f"调研日期：{date}。本目录整理 {len(records)} 项代表性论文／投稿记录。",
        "资料字段与逐项注释统一维护于 [catalog.json](catalog.json)；本页与 [BibTeX](references.bib)由维护工具生成。",
        "",
        "阅读策略与设计比较见 [研究综述](../research-landscape.md)；出处核验及读取限制见 [检索记录](search-log.md)，实现考察见 [源码记录](source-inspection.md)。",
        "",
        "更新 catalog 后运行 `python3 scripts/render_references.py`，再运行仓库校验。当前资料是定向代表性综述；各条目说明实际阅读范围，不构成复现实验或性能排行榜。",
        "",
        "## 资料索引",
        "",
        "| ID | 工作 | 类别 |",
        "|---|---|---|",
    ]
    for record in records:
        markdown.append(
            f"| [{record['id']}](#{record['id'].lower()}) | {record['short_name']} | {record['category']} |"
        )
    markdown.extend(["", "## 逐项资料", ""])
    bibliography = [f"% Generated from catalog.json; sources accessed {date}.", ""]
    for record in records:
        identifier = record["id"]
        authors = record["authors"]
        author_text = "、".join(authors[:3]) + (" 等" if len(authors) > 3 else "")
        year = record.get("citation_year", record["year"])
        links = [f"[论文]({record['paper_url']})", f"[PDF]({record['pdf_url']})"]
        if record.get("publication_url"):
            links.append(f"[出版记录]({record['publication_url']})")
        if record.get("code_url"):
            links.append(f"[作者代码／项目]({record['code_url']})")
        markdown.extend([
            f'<a id="{identifier.lower()}"></a>', "",
            f"### {identifier} · {record['short_name']}", "",
            f"{author_text or '作者未核验'}（{year}）。**{record['title']}**。{record['publication']}。", "",
            " · ".join(links) + f" · 引用键：`{record['citation_key']}`。", "",
            f"元数据版本：`{record['metadata_version'] or '未提供 arXiv 版本'}`。阅读范围：{record['read_scope']}。", "",
            f"- **作者做了什么**：{record['method_summary']}",
            f"- **证据说明什么**：{record['evidence_scope']}",
            f"- **本项目如何使用**：{record['design_implication']}", "",
        ])
        fields = {
            "title": "{" + record["title"] + "}",
            "year": str(year),
            "url": record.get("publication_url") or record["paper_url"],
            "note": f"{record['publication']}; metadata accessed {record.get('access_date', date)}",
        }
        if authors:
            fields["author"] = " and ".join(authors)
        if record.get("arxiv_id"):
            fields.update(eprint=record["arxiv_id"], archivePrefix="arXiv")
            fields["primaryClass"] = record["primary_category"]
        for field in ["doi", "journal", "booktitle"]:
            if record.get(field):
                fields[field] = record[field]
        bibliography.append(f"@{record['citation_type']}{{{record['citation_key']},")
        bibliography.extend(f"  {key} = {{{value}}}," for key, value in fields.items())
        bibliography.extend(["}", ""])
    markdown.extend([
        "## 维护与引用", "",
        "论文 ID、出版状态、模型、推理流程与数据集分别记录。同名 OptiBench 使用 R11/R12 区分；未知作者与发表决定保持未核验。", "",
        "正式发表年份与预印本年份可以不同，引用年份来自 catalog 的 citation_year 或首次提交年份。当前资料由 AI 辅助整理；阅读范围逐项记录，本次未运行第三方系统。", "",
    ])
    return {"README.md": "\n".join(markdown), "references.bib": "\n".join(bibliography)}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Report stale generated files without writing")
    args = parser.parse_args()
    try:
        catalog = json.loads((DIRECTORY / "catalog.json").read_text())
        for filename, text in render(catalog).items():
            target = DIRECTORY / filename
            if args.check:
                if not target.exists() or target.read_text() != text:
                    print(f"generated references out of date: {filename}")
                    return 1
            else:
                target.write_text(text, encoding="utf-8")
    except (OSError, KeyError, TypeError, ValueError) as error:
        print(f"Invalid reference catalog: {error}")
        return 1
    print("Reference rendering checked" if args.check else "References rendered")
    return 0


if __name__ == "__main__":
    sys.exit(main())
